\label{lemma:pi-properties}
Let $X$ be a normal surface with rational singularities and let $\pi \colon {\widetilde{X}} \to X$ be its resolution.
The functor $\pi^* \colon {\mathbf{D}}^-(X) \to {\mathbf{D}}^-({\widetilde{X}})$ is fully faithful.
The functor $\pi_* \colon {\mathbf{D}}^-({\widetilde{X}}) \to {\mathbf{D}}^-(X)$ is its right adjoint, 
it preserves boundedness, and there is an isomorphism of functors
\begin{equation}\label{eq:pis-pis-id}
\pi_* \circ \pi^* \cong \mathrm{id}.
\end{equation}
Moreover, 
\begin{equation*}
\mathrm{Im} \pi^* = {}^\perp\langle {\mathscr{O}}_\Delta(-1) \rangle_{\Delta \in {\boldsymbol\Delta}}
\qquad\text{and}\qquad
\mathrm{Ker} \pi_* = \langle {\mathscr{O}}_\Delta(-1) \rangle^\oplus_{\Delta \in {\boldsymbol\Delta}},
\end{equation*}
where $\langle - \rangle^\oplus$ denotes the minimal triangulated subcategory closed under infinite direct sums defined in ${\mathbf{D}}^-$.

The pullback-pushforward adjunction is standard.
By projection formula we have
\begin{equation*}
\pi_*(\pi^*{\mathscr{F}}) \cong {\mathscr{F}} \otimes \pi_*{\mathscr{O}}_{\widetilde{X}},
\end{equation*}
and since $X$ has rational singularities, the canonical morphism ${\mathscr{O}}_X \to \pi_*{\mathscr{O}}_{\widetilde{X}}$ is an isomorphism, hence~\eqref{eq:pis-pis-id} holds.
By adjunction it follows that $\pi^*$ is fully faithful.
Finally, by~\cite[Lemma~2.1]{bodzenta2015flops} (see also~\cite[Lemma~3.1]{bridgeland} and Lemma~\ref{lemma:spectral} below) and~\cite[Proposition~9.14 and Theorem~9.15]{bodzenta2015flops}
the category $\mathrm{Ker}\pi_*$ is generated by sheaves ${\mathscr{O}}_\Delta(-1)$.
The description of $\mathrm{Im}\pi^*$ follows by adjunction.

\label{lemma:spectral}
Let $\pi \colon {\widetilde{X}} \to X$ be a proper morphism with fibers of dimension at most~$1$.
Let ${\mathscr{F}}$ be a possibly unbounded complex of quasicoherent sheaves on ${\widetilde{X}}$ and let ${\mathscr{H}}^i({\mathscr{F}})$ be its cohomology sheaf in degree $i$.
The spectral sequence $R^i\pi_*({\mathscr{H}}^j({\mathscr{F}})) \Rightarrow {\mathscr{H}}^{i+j}(\pi_*({\mathscr{F}}))$ degenerates at the second page, 
and gives for each $i$ an exact sequence
\begin{equation*}
0 \to R^1\pi_*{\mathscr{H}}^{i-1}({\mathscr{F}}) \to {\mathscr{H}}^i(\pi_*({\mathscr{F}})) \to R^0\pi_*{\mathscr{H}}^i({\mathscr{F}}) \to 0.
\end{equation*}
In particular, if ${\mathscr{H}}^i(\pi_*({\mathscr{F}})) = 0$ for $i \le p$ for some integer $p$, then $\pi_*({\mathscr{H}}^i({\mathscr{F}})) = 0$ for $i \le p - 1$ and
\begin{equation*}
\pi_*{\mathscr{F}} \cong \pi_*(\tau^{\ge p}{\mathscr{F}}),
\end{equation*}
where $\tau$ stands for the truncation functor with respect to the canonical filtration.

In particular, if ${\mathscr{H}}^i(\pi_*({\mathscr{F}})) = 0$ for $i \le p$ for some integer $p$, then $\pi_*({\mathscr{H}}^i({\mathscr{F}})) = 0$ for $i \le p - 1$ and
\begin{equation*}
\pi_*{\mathscr{F}} \cong \pi_*(\tau^{\ge p}{\mathscr{F}}),
\end{equation*}
where $\tau$ stands for the truncation functor with respect to the canonical filtration.

\label{proposition:serre-gorenstein}
Let $X$ be a projective Gorenstein ${\mathsf{k}}$-scheme of dimension $n$.
If either ${\mathscr{F}}$ or ${\mathscr{G}}$ is a perfect complex, there is a natural Serre duality isomorphism
\begin{equation*}
\mathrm{Ext}^i({\mathscr{F}},{\mathscr{G}})^\vee \cong \mathrm{Ext}^{n-i}({\mathscr{G}},{\mathscr{F}} \otimes \omega_X).
\end{equation*}

it follows that the usual duality functor
\begin{equation*}
{\mathscr{F}} \mapsto {\mathscr{F}}^\vee := \mathrm{R}\mathscr{H}\mathit{om}({\mathscr{F}},{\mathscr{O}}_X) \cong \mathrm{R}\mathscr{H}\mathit{om}({\mathscr{F}},\omega_X^\bullet) \otimes \omega_X^{-1}[-\dim X]
\end{equation*}

\begin{equation*}
{\mathscr{F}} \mapsto {\mathscr{F}}^\vee := \mathrm{R}\mathscr{H}\mathit{om}({\mathscr{F}},{\mathscr{O}}_X) \cong \mathrm{R}\mathscr{H}\mathit{om}({\mathscr{F}},\omega_X^\bullet) \otimes \omega_X^{-1}[-\dim X]
\end{equation*}
is also an equivalence of categories ${\mathbf{D}}(X)^{\mathrm{opp}} \xrightarrow{\ \sim\ } {\mathbf{D}}(X)$.

\label{proposition:tx-excol}
Let $X$ be a sextic du Val del Pezzo surface over an algebraically closed field ${\mathsf{k}}$ 
and let~$\pi \colon {\widetilde{X}} \to X$ be its minimal resolution of singularities. 
There is a semiorthogonal decomposition
\begin{equation}
\label{eq:dbtx}
{\mathbf{D}}({\widetilde{X}}) = \langle {\widetilde{{\mathcal{A}}}}_1, {\widetilde{{\mathcal{A}}}}_2, {\widetilde{{\mathcal{A}}}}_3  \rangle,
\end{equation}
whose components are generated by the following exceptional collections of line bundles
\begin{equation}
\begin{aligned}
\label{eq:tx-excol}
{\widetilde{{\mathcal{A}}}}_1 &= \langle {\mathscr{O}}_{\widetilde{X}} \rangle,\\
{\widetilde{{\mathcal{A}}}}_2 &= \langle {\mathscr{O}}_{\widetilde{X}}(h - e_1), {\mathscr{O}}_{\widetilde{X}}(h - e_2), {\mathscr{O}}_{\widetilde{X}}(h - e_3) \rangle,\\
{\widetilde{{\mathcal{A}}}}_3 &= \langle {\mathscr{O}}_{\widetilde{X}}(h), {\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3) \rangle. 
\end{aligned}
\end{equation}

the following exceptional collections of line bundles
\begin{equation}
\begin{aligned}
\label{eq:tx-excol}
{\widetilde{{\mathcal{A}}}}_1 &= \langle {\mathscr{O}}_{\widetilde{X}} \rangle,\\
{\widetilde{{\mathcal{A}}}}_2 &= \langle {\mathscr{O}}_{\widetilde{X}}(h - e_1), {\mathscr{O}}_{\widetilde{X}}(h - e_2), {\mathscr{O}}_{\widetilde{X}}(h - e_3) \rangle,\\
{\widetilde{{\mathcal{A}}}}_3 &= \langle {\mathscr{O}}_{\widetilde{X}}(h), {\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3) \rangle. 
\end{aligned}
\end{equation}

\begin{equation}
\begin{aligned}
\label{eq:tx-excol}
{\widetilde{{\mathcal{A}}}}_1 &= \langle {\mathscr{O}}_{\widetilde{X}} \rangle,\\
{\widetilde{{\mathcal{A}}}}_2 &= \langle {\mathscr{O}}_{\widetilde{X}}(h - e_1), {\mathscr{O}}_{\widetilde{X}}(h - e_2), {\mathscr{O}}_{\widetilde{X}}(h - e_3) \rangle,\\
{\widetilde{{\mathcal{A}}}}_3 &= \langle {\mathscr{O}}_{\widetilde{X}}(h), {\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3) \rangle. 
\end{aligned}
\end{equation}

\label{lemma:dual-sod-tx}
The semiorthogonal decomposition~\eqref{eq:dbtx-dual} is right mutation-dual to~\eqref{eq:dbtx}, i.e., 
\begin{equation*}
{\widetilde{{\mathcal{A}}}}_1^\vee = {\widetilde{{\mathcal{A}}}}_1,
\qquad
{\widetilde{{\mathcal{A}}}}_2^\vee = {\mathbb{L}}_{{\widetilde{{\mathcal{A}}}}_1}({\widetilde{{\mathcal{A}}}}_2),
\quad\text{and}\quad 
{\widetilde{{\mathcal{A}}}}_3^\vee = {\mathbb{L}}_{{\widetilde{{\mathcal{A}}}}_1}({\mathbb{L}}_{{\widetilde{{\mathcal{A}}}}_2}({\widetilde{{\mathcal{A}}}}_3)) = {\widetilde{{\mathcal{A}}}}_3 \otimes \omega_{\widetilde{X}}.
\end{equation*}

The claim is trivial for the first component, since ${\widetilde{{\mathcal{A}}}}_1^\vee  = \langle {\mathscr{O}}_{\widetilde{X}}^\vee  \rangle = \langle {\mathscr{O}}_{\widetilde{X}} \rangle = {\widetilde{{\mathcal{A}}}}_1$,
and is easy for the last component, since ${\mathbb{L}}_{{\widetilde{{\mathcal{A}}}}_1}({\mathbb{L}}_{{\widetilde{{\mathcal{A}}}}_2}({\widetilde{{\mathcal{A}}}}_3)) = {\widetilde{{\mathcal{A}}}}_3  \otimes \omega_{\widetilde{X}}$ and
\begin{equation}\label{eq:ce3-dual}
\begin{aligned}
& {\mathscr{O}}_{\widetilde{X}}(h) \otimes \omega_{\widetilde{X}} && \cong {\mathscr{O}}_{\widetilde{X}}(-2h + e_1 + e_2 + e_3) && \cong {\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3)^\vee,\\
& {\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3) \otimes \omega_{\widetilde{X}} && \cong {\mathscr{O}}_{\widetilde{X}}(-h) && \cong {\mathscr{O}}_{\widetilde{X}}(h)^\vee.
\end{aligned}
\end{equation} 
Finally, for the second component we have 
${\mathbb{L}}_{{\widetilde{{\mathcal{A}}}}_1}({\widetilde{{\mathcal{A}}}}_2) = {\widetilde{{\mathcal{A}}}}_1^\perp \cap {\widetilde{{\mathcal{A}}}}_3^\perp = ({\widetilde{{\mathcal{A}}}}_1^\vee)^\perp \cap  {}^\perp({\widetilde{{\mathcal{A}}}}_3 \otimes \omega_X) = {\widetilde{{\mathcal{A}}}}_2^\vee$
by Serre duality.

\begin{equation}\label{eq:ce3-dual}
\begin{aligned}
& {\mathscr{O}}_{\widetilde{X}}(h) \otimes \omega_{\widetilde{X}} && \cong {\mathscr{O}}_{\widetilde{X}}(-2h + e_1 + e_2 + e_3) && \cong {\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3)^\vee,\\
& {\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3) \otimes \omega_{\widetilde{X}} && \cong {\mathscr{O}}_{\widetilde{X}}(-h) && \cong {\mathscr{O}}_{\widetilde{X}}(h)^\vee.
\end{aligned}
\end{equation}

The component ${\widetilde{{\mathcal{A}}}}_1$ is generated by a single exceptional object, hence is equivalent to ${\mathbf{D}}({\mathsf{k}})$.
So, in view of Proposition~\ref{proposition:rm-equivalence} to prove the proposition it is enough to compute $\mathrm{Ext}$-spaces 
between the exceptional line bundles forming the components ${\widetilde{{\mathcal{A}}}}_2$ and ${\widetilde{{\mathcal{A}}}}_3$ of the semiorthogonal decomposition~\eqref{eq:dbtx}.

First of all, we have
\begin{equation*}
\mathrm{Ext}^p({\mathscr{O}}_{\widetilde{X}}(h-e_i), {\mathscr{O}}_{\widetilde{X}}(h-e_j)) \cong H^p({\widetilde{X}}, {\mathscr{O}}_{\widetilde{X}}(e_i - e_j)).
\end{equation*}
Assuming $i \ne j$ and using exact sequences (note that $e_i\cdot e_j = 0$ and $e_i^2 = -1$ by Lemma~\ref{lemma:pic-tx})
\begin{equation*}
0 \to {\mathscr{O}}_{\widetilde{X}}(e_i - e_j) \to {\mathscr{O}}_{\widetilde{X}}(e_i) \to {\mathscr{O}}_{E_j} \to 0,
\qquad\qquad
0 \to {\mathscr{O}}_{\widetilde{X}} \to {\mathscr{O}}_{\widetilde{X}}(e_i) \to {\mathscr{O}}_{E_i}(-1) \to 0,
\end{equation*}
we obtain an exact sequence
\begin{equation*}
0 \to H^0({\widetilde{X}}, {\mathscr{O}}_{\widetilde{X}}(e_i - e_j)) \to {\mathsf{k}} \to {\mathsf{k}} \to H^1({\widetilde{X}}, {\mathscr{O}}_{\widetilde{X}}(e_i - e_j)) \to 0,
\end{equation*}
where the middle map is given by the restriction to $E_j$ of the equation of $E_i$.
This restriction vanishes if and only if $E_j$ is a component of $E_i$ --- in this case we deduce that $\mathrm{Ext}^\bullet({\mathscr{O}}_{\widetilde{X}}(h-e_i), {\mathscr{O}}_{\widetilde{X}}(h-e_j)) \cong {\mathsf{k}} \oplus {\mathsf{k}}[-1]$,
and otherwise $\mathrm{Ext}^\bullet({\mathscr{O}}_{\widetilde{X}}(h-e_i), {\mathscr{O}}_{\widetilde{X}}(h-e_j)) = 0$.
By Proposition~\ref{proposition:rm-equivalence} this gives the required description of ${\widetilde{{\mathcal{A}}}}_2$ in types from~0 to 3.
In the last two types (4 and 5) it remains to check that multiplication map
\begin{equation}\label{eq:multiplication-ext-tx}
\mathrm{Ext}^p({\mathscr{O}}_{\widetilde{X}}(h-e_1),{\mathscr{O}}_{\widetilde{X}}(h-e_2)) \otimes \mathrm{Ext}^q({\mathscr{O}}_{\widetilde{X}}(h-e_2),{\mathscr{O}}_{\widetilde{X}}(h-e_3)) \to \mathrm{Ext}^{p+q}({\mathscr{O}}_{\widetilde{X}}(h-e_1),{\mathscr{O}}_{\widetilde{X}}(h-e_3))
\end{equation}
is an isomorphism when $p = 0$ or $q = 0$.
For this consider exact sequences
\begin{equation}\label{eq:e12}
0 \to {\mathscr{O}}_{\widetilde{X}}(h - e_1) \xrightarrow{\ \Delta_{12}\ } {\mathscr{O}}_{\widetilde{X}}(h - e_2) \to {\mathscr{O}}_{\Delta_{12}}(-1) \to 0,
\end{equation}
\begin{equation}\label{eq:e23}
0 \to {\mathscr{O}}_{\widetilde{X}}(h - e_2) \xrightarrow{\ \Delta_{23}\ } {\mathscr{O}}_{\widetilde{X}}(h - e_3) \to {\mathscr{O}}_{\Delta_{23}}(-1) \to 0,
\end{equation}
where $\Delta_{12} = E_1 - E_2$ and $\Delta_{23} = E_2 - E_3$.
Using Lemma~\ref{lemma:pic-tx}, we compute
\begin{equation*}
\mathrm{Ext}^\bullet({\mathscr{O}}_{\widetilde{X}}(h-e_1),{\mathscr{O}}_{\Delta_{23}}(-1)) \cong
H^\bullet(\Delta_{23},{\mathscr{O}}_{\widetilde{X}}(e_1 - h)\vert_{\Delta_{23}} \otimes {\mathscr{O}}_{\Delta_{23}}(-1)) =
H^\bullet(\Delta_{23},{\mathscr{O}}_{\Delta_{23}}(-1)) = 0.
\end{equation*}
Applying the functor $\mathrm{Ext}^\bullet({\mathscr{O}}_{\widetilde{X}}(h-e_1),-)$ to~\eqref{eq:e23}, we deduce that~\eqref{eq:multiplication-ext-tx} is an isomorphism for~$q = 0$. 
Similarly, by Serre duality $\mathrm{Ext}^\bullet({\mathscr{O}}_{\Delta_{12}}(-1),{\mathscr{O}}_{\widetilde{X}}(h-e_3))$ is dual to $\mathrm{Ext}^\bullet({\mathscr{O}}_{\widetilde{X}}(e_1 + e_2 - 2h),{\mathscr{O}}_{\Delta_{12}}(-1))$, and
a computation similar to the above shows it is zero.
Applying the functor $\mathrm{Ext}^\bullet(-,{\mathscr{O}}_{\widetilde{X}}(h-e_3))$ to~\eqref{eq:e12}, we deduce that~~\eqref{eq:multiplication-ext-tx} is an isomorphism for $p = 0$. 

To describe ${\widetilde{{\mathcal{A}}}}_3$ we only need to compute 
\begin{equation*}
\mathrm{Ext}^p({\mathscr{O}}_{\widetilde{X}}(h), {\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3)) \cong H^p({\widetilde{X}}, {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2 - e_3)).
\end{equation*}
Using exact sequences
\begin{align*}
0 \to {\mathscr{O}}_{\widetilde{X}}(h - e_1) \to {\mathscr{O}}_{\widetilde{X}}(h) &\to {\mathscr{O}}_{E_1} \to 0,\\
0 \to {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2) \to {\mathscr{O}}_{\widetilde{X}}(h - e_1) &\to {\mathscr{O}}_{E_2} \to 0,\\
0 \to {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2 - e_3) \to {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2) &\to {\mathscr{O}}_{E_3} \to 0,
\end{align*}
we conclude that $H^\bullet({\widetilde{X}}, {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2 - e_3)) = 0$ 
if the three centers of the blowups are not contained on a line (i.e., in types~0, 2, and 4), and 
$H^0({\widetilde{X}}, {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2 - e_3)) = H^1({\widetilde{X}}, {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2 - e_3)) = {\mathsf{k}}$ otherwise.
By Proposition~\ref{proposition:rm-equivalence} this describes ${\widetilde{{\mathcal{A}}}}_3$.

\begin{equation*}
\mathrm{Ext}^p({\mathscr{O}}_{\widetilde{X}}(h), {\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3)) \cong H^p({\widetilde{X}}, {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2 - e_3)).
\end{equation*}

\begin{align*}
0 \to {\mathscr{O}}_{\widetilde{X}}(h - e_1) \to {\mathscr{O}}_{\widetilde{X}}(h) &\to {\mathscr{O}}_{E_1} \to 0,\\
0 \to {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2) \to {\mathscr{O}}_{\widetilde{X}}(h - e_1) &\to {\mathscr{O}}_{E_2} \to 0,\\
0 \to {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2 - e_3) \to {\mathscr{O}}_{\widetilde{X}}(h - e_1 - e_2) &\to {\mathscr{O}}_{E_3} \to 0,
\end{align*}

\label{lemma:ker-pis}
We have 
\begin{equation*}
{\widetilde{{\mathcal{A}}}}_1^- \cap \mathrm{Ker} \pi_* = 0,
\qquad 
{\widetilde{{\mathcal{A}}}}_2^- \cap \mathrm{Ker} \pi_* = \langle {\mathscr{O}}_{\Delta}(-1) \rangle^\oplus_{\Delta \in {\boldsymbol\Delta}_2},
\quad\text{and}\quad
{\widetilde{{\mathcal{A}}}}_3^- \cap \mathrm{Ker} \pi_* = \langle {\mathscr{O}}_{\Delta}(-1) \rangle^\oplus_{\Delta \in {\boldsymbol\Delta}_3}.
\end{equation*}
Moreover, for any ${\mathscr{F}} \in \mathrm{Ker}\pi_* \subset {\mathbf{D}}^-({\widetilde{X}})$ there is a canonical direct sum decomposition 
\begin{equation*}
{\mathscr{F}} = {\mathscr{F}}_2 \oplus {\mathscr{F}}_3
\end{equation*}
with ${\mathscr{F}}_j \in {\widetilde{{\mathcal{A}}}}_j^- \cap \mathrm{Ker} \pi_*$.

\label{proposition:sod-dbx-}
The subcategories ${\mathcal{A}}_i^- = \{ {\mathscr{F}} \in {\mathbf{D}}^-(X) \mid  \pi^*({\mathscr{F}}) \in {\widetilde{{\mathcal{A}}}}_i^- \} \subset {\mathbf{D}}^-(X)$ form a semiorthogonal decomposition
\begin{equation*}
{\mathbf{D}}^-(X) = \langle {\mathcal{A}}_1^-, {\mathcal{A}}_2^-, {\mathcal{A}}_3^- \rangle
\end{equation*}
with projection functors given by
\begin{equation}
\label{eq:alpha}
\alpha_i = \pi_* \circ \tilde\alpha_i \circ \pi^*.
\end{equation}
Moreover, we have
\begin{equation}\label{eq:pis-ai}
\pi_*({\widetilde{{\mathcal{A}}}}_i^-) = {\mathcal{A}}_i^-.
\end{equation}

\label{proposition:sod-dbx}
The subcategories 
\begin{equation*}
{\mathcal{A}}_i := {\mathcal{A}}_i^- \cap {\mathbf{D}}(X) = \{ {\mathscr{F}} \in {\mathbf{D}}(X) \mid \pi^*({\mathscr{F}}) \in {\widetilde{{\mathcal{A}}}}_i^- \} \subset {\mathbf{D}}(X)
\end{equation*}
provide a semiorthogonal decomposition~\eqref{eq:dbx}.
Its projection functors $\alpha_i$ are given by~\eqref{eq:alpha}; they preserve boundedness and have finite cohomological amplitude.
Finally, ${\mathcal{A}}_i = \pi_*({\widetilde{{\mathcal{A}}}}_i)$.

\label{proposition:gamma}
The functor 
\begin{equation}\label{def:gamma}
\gamma := \pi_* \circ \tilde\gamma \circ \pi_m^* \colon {\mathbf{D}}^-({\mathsf{k}}[t]/t^m) \to {\mathbf{D}}^-(X).
\end{equation}
is fully faithful and preserves boundedness.
Moreover, the diagrams
\begin{equation}
\label{eq:gamma-tgamma}
\vcenter{\xymatrix@C=5em{
{\mathbf{D}}^-({\tilde{R}}_m) \ar[r]^-{\tilde\gamma} \ar[d]_{\pi_{m*}} &
{\mathbf{D}}^-({\widetilde{X}}) \ar[d]^{\pi_{*}} 
\\
{\mathbf{D}}^-({\mathsf{k}}[t]/t^m) \ar[r]^{\gamma} &
{\mathbf{D}}^-(X)
}}
\qquad\text{and}\qquad
\vcenter{\xymatrix@C=5em{
{\mathbf{D}}^-({\tilde{R}}_m) \ar[r]^-{\tilde\gamma} &
{\mathbf{D}}^-({\widetilde{X}})  
\\
{\mathbf{D}}^-({\mathsf{k}}[t]/t^m) \ar[r]^{\gamma} \ar[u]^{\pi_m^{*}} &
{\mathbf{D}}^-(X) \ar[u]_{\pi^{*}}
}}
\end{equation}
are both commutative.

\label{proposition:sod-cai}
The fully faithful functors $\gamma_1,\dots,\gamma_s$ induce a completely orthogonal decomposition 
\begin{equation*}
{\mathcal{A}}_i = {\mathbf{D}}({\mathsf{k}}[t]/t^{m_1}) \times \dots \times {\mathbf{D}}({\mathsf{k}}[t]/t^{m_s}).
\end{equation*}

Consider the semiorthogonal decompositions
\begin{equation*}
{\mathbf{D}}({\widetilde{X}}) = \langle {\widetilde{{\mathcal{A}}}}_3 \otimes \omega_{\widetilde{X}}, {\widetilde{{\mathcal{A}}}}_1, {\widetilde{{\mathcal{A}}}}_2 \rangle
\qquad\text{and}\qquad
{\mathbf{D}}({\widetilde{X}}) = \langle {\widetilde{{\mathcal{A}}}}_2 \otimes \omega_{\widetilde{X}}, {\widetilde{{\mathcal{A}}}}_3 \otimes \omega_{\widetilde{X}}, {\widetilde{{\mathcal{A}}}}_1 \rangle,
\end{equation*}
obtained from~\eqref{eq:dbtx} by mutations.
Since $\omega_{\widetilde{X}} \cong \pi^*\omega_X$ and $\omega_X$ is a line bundle on $X$, we have 
\begin{equation*}
\pi_*({\widetilde{{\mathcal{A}}}}_i \otimes \omega_{\widetilde{X}}) = \pi_*({\widetilde{{\mathcal{A}}}}_i) \otimes \omega_X = {\mathcal{A}}_i \otimes \omega_X,
\end{equation*}
hence the arguments of this subsection also prove semiorthogonal decompositions


\begin{equation}\label{eq:dbx-other}
{\mathbf{D}}(X) = \langle {\mathcal{A}}_3 \otimes \omega_X, {\mathcal{A}}_1, {\mathcal{A}}_2 \rangle
\qquad\text{and}\qquad
{\mathbf{D}}(X) = \langle {\mathcal{A}}_2 \otimes \omega_X, {\mathcal{A}}_3 \otimes \omega_X, {\mathcal{A}}_1 \rangle.
\end{equation}
Since the twist by $\omega_X$ is an autoequivalence of ${\mathbf{D}}(X)$, these decompositions together with~\eqref{eq:dbx} 
show that each ${\mathcal{A}}_i$ is admissible.
Indeed, (up to a twist) each ${\mathcal{A}}_i$ appears in one of the three decompositions on the left, and in one on the right,
hence it is both left and right admissible.

\label{proposition:dbx-dual}
If $X$ is a sextic del Pezzo surface over an algebraically closed field, there is a semiorthogonal decomposition 
\begin{equation}
\label{eq:dbx-dual}
{\mathbf{D}}(X) = \langle {\mathcal{A}}_3^\vee, {\mathcal{A}}_2^\vee, {\mathcal{A}}_1^\vee \rangle,
\end{equation}
where
\begin{equation*}
{\mathcal{A}}_i^\vee := \{ {\mathscr{F}} \in {\mathbf{D}}(X) \mid {\mathscr{F}}^\vee \in {\mathcal{A}}_i \} \cong {\mathbf{D}}(Z_i),
\end{equation*}
and ${\mathcal{A}}_i$ are the components of~\eqref{eq:dbx}.
Moreover, this semiorthogonal decomposition 
is right mutation-dual to~\eqref{eq:dbx}, i.e., ${\mathcal{A}}_1^\vee = {\mathcal{A}}_1$, ${\mathcal{A}}_2^\vee = {\mathbb{L}}_{{\mathcal{A}}_1}({\mathcal{A}}_2)$ and ${\mathcal{A}}_3^\vee = {\mathbb{L}}_{{\mathcal{A}}_1}({\mathbb{L}}_{{\mathcal{A}}_2}({\mathcal{A}}_3))$.

\label{lemma:sheaves-y-z}
Let $Z = \mathrm{Spec}({\mathsf{k}}[t]/t^m)$.
For any scheme $Y$ we have an equivalence 
\begin{equation*}
\mathrm{coh}(Y \times Z) \cong \mathrm{coh}(Y,{\mathscr{O}}_Y[t]/t^m),
\end{equation*}
where the right hand side is the category of coherent sheaves ${\mathscr{F}}$ on $Y$ with an operator $t \colon {\mathscr{F}} \to {\mathscr{F}}$ such that $t^m = 0$.
An object $({\mathscr{F}},t) \in \mathrm{coh}(Y,{\mathscr{O}}_Y[t]/t^m)$ considered as a sheaf on $Y \times Z$ is flat over $Z$ if and only if all the maps in the next chain of epimorphisms
\begin{equation}\label{eq:t-quotients}
\xymatrix@1{{\mathscr{F}}/(t{\mathscr{F}}) \ar@{->>}[r]^-t & (t{\mathscr{F}})/(t^2{\mathscr{F}}) \ar@{->>}[r]^-t & \ \dots\  \ar@{->>}[r]^-t & (t^{m-1}{\mathscr{F}})/(t^m{\mathscr{F}})}
\end{equation}
are isomorphisms.

\label{lemma:e-z-small}
$(1)$ 
If $z$ is the unique closed ${\mathsf{k}}$-point of $Z_1$ then $\gamma_{Z_1}({\mathscr{O}}_z) \cong {\mathscr{O}}_X \cong \pi_*{\mathscr{O}}_{\widetilde{X}}$.


\noindent$(2)$
Let $z \in Z_2$ be a closed ${\mathsf{k}}$-point and let ${\mathscr{E}}_z := \gamma_{Z_2}({\mathscr{O}}_z) \in {\mathbf{D}}(X)$ be the corresponding object.
Then
\begin{itemize}
\item[(a)] 
if the component of $Z_2$ containing $z$ is reduced and corresponds to the $i$-th blowup center, then 
\begin{equation*}
{\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h-e_i);
\end{equation*}
\item[(b)] 
if the component of $Z_2$ containing $z$ has length $2$
then 
\begin{equation*}
{\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h-e_1) \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h - e_2);
\end{equation*}
\item[(c)] 
if the component of $Z_2$ containing $z$ has length $3$, then
\begin{equation*}
{\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h-e_1) \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h - e_2) \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h - e_3).
\end{equation*}
\end{itemize}
\noindent$(3)$
Let $z \in Z_3$ be a closed ${\mathsf{k}}$-point and let ${\mathscr{E}}_z := \gamma_{Z_3}({\mathscr{O}}_z) \in {\mathbf{D}}(X)$ be the corresponding object.
Then
\begin{itemize}
\item[(a)] 
if the component of $Z_3$ containing $z$ is reduced then 
\begin{equation*}
{\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h)
\qquad\text{or}\qquad 
{\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3);
\end{equation*}
\item[(b)] 
if the component of $Z_3$ containing $z$ has length $2$ then 
\begin{equation*}
{\mathscr{E}}_z \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(h) \cong \pi_*{\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3).
\end{equation*}
\end{itemize}
In all these cases, ${\mathscr{E}}_z$ is a globally generated sheaf, and if $z \in Z_d$ then
\begin{equation*}
\dim H^0(X,{\mathscr{E}}_z) = d
\qquad\text{and}\qquad
H^{i}(X,{\mathscr{E}}_z) = 0
\quad\text{for $i \ne 0$}.
\end{equation*}

\label{proposition:e-z-big}
Both ${\mathfrak{E}}_Z$ and ${\widetilde{{\mathfrak{E}}}}_Z$ are vector bundles of rank~$\ell(Z)$ on~$X$ and~${\widetilde{X}}$ respectively, and
\begin{equation}
\label{eq:ez-pullback}
{\mathfrak{E}}_Z \cong \pi_*({\widetilde{{\mathfrak{E}}}}_Z).
\end{equation}
Moreover, ${\mathfrak{E}}_Z$ is an iterated extension of the sheaf ${\mathscr{E}}_z$, where $z$ is the closed point of~$Z$.
In particular, the bundle ${\mathfrak{E}}_Z$ is globally generated with $\dim H^0(X,{\mathfrak{E}}_Z) = d\ell(Z)$ and $H^i(X,{\mathfrak{E}}_Z) = 0$ for $i \ne 0$.

\label{proposition:fm-zd}
For each $d \in \{1,2,3\}$ there is a sheaf 
\begin{equation*}
{\mathscr{E}}_{Z_d} \in \mathrm{coh}(X \times Z_d),
\end{equation*}
flat over $Z_d$, such that $p_{X*}{\mathscr{E}}_{Z_d} \cong {\mathfrak{E}}_{Z_d}$, and the equivalence $\gamma_{Z_d} \colon {\mathbf{D}}(Z_d) \to {\mathcal{A}}_d \subset {\mathbf{D}}(X)$ of Corollary~\textup{\ref{corollary:dbx-z2-z3}} can be written as
\begin{equation*}
\gamma_{Z_d} \cong \Phi_{{\mathscr{E}}_{Z_d}} \colon {\mathbf{D}}(Z_d) \to {\mathbf{D}}(X),
\end{equation*}
where $\Phi_{{\mathscr{E}}_{Z_d}}$ is the Fourier--Mukai functor with kernel ${\mathscr{E}}_{Z_d}$.
Moreover, the equivalence \mbox{${\mathbf{D}}(Z_d) \cong {\mathcal{A}}_d^\vee \subset {\mathbf{D}}(X)$} of Proposition~\textup{\ref{proposition:dbx-dual}} is given by the Fourier--Mukai functor $\Phi_{{\mathscr{E}}_{Z_d}^\vee}$ with kernel ${\mathscr{E}}_{Z_d}^\vee$.

\label{corollary:a-as-orthogonals}
The components ${\mathcal{A}}_2$ and ${\mathcal{A}}_3$ of ${\mathbf{D}}(X)$ are compactly generated by the bundles ${\mathfrak{E}}_{Z_2}$ and~${\mathfrak{E}}_{Z_3}$ respectively.
In particular, we have ${\mathcal{A}}_2 = {}^\perp {\mathscr{O}}_X \cap {\mathfrak{E}}_{Z_3}^\perp$ and ${\mathcal{A}}_3 = {}^\perp {\mathscr{O}}_X \cap {}^\perp{\mathfrak{E}}_{Z_2}$.

By Corollary~\ref{corollary:pis-epi} we can write ${\mathscr{F}} = \pi_*{\widetilde{{\mathscr{F}}}}$ for some ${\widetilde{{\mathscr{F}}}} \in {\mathbf{D}}({\widetilde{X}})$, hence by adjunction
\begin{equation*}
\chi({\mathfrak{E}}_{Z_d}, {\mathscr{F}}) = \chi({\mathfrak{E}}_{Z_d},\pi_*{\widetilde{{\mathscr{F}}}}) = \chi(\pi^*{\mathfrak{E}}_{Z_d},{\widetilde{{\mathscr{F}}}}) = \chi({\widetilde{{\mathfrak{E}}}}_{Z_d},{\widetilde{{\mathscr{F}}}}).
\end{equation*}
As it is explained in Proposition~\ref{proposition:e-z-big} the bundle ${\widetilde{{\mathfrak{E}}}}_{Z_2}$ 
is an extension (possibly trivial) of the line bundles~${\mathscr{O}}_{\widetilde{X}}(h-e_i)$ for $i = 1,2,3$, hence 
\begin{equation*}
\mathrm{ch}({\widetilde{{\mathfrak{E}}}}_{Z_2}) = \sum \mathrm{ch}({\mathscr{O}}_{\widetilde{X}}(h-e_i)) = 3 + (3h - e_1 - e_2 - e_3) = 3 - K_{\widetilde{X}} = 2\mathrm{ch}({\mathscr{O}}_{\widetilde{X}}) + \mathrm{ch}(\omega_{\widetilde{X}}^{-1}) - 3\mathrm{ch}({\mathscr{O}}_{\widetilde{P}}),
\end{equation*}
where ${\widetilde{P}}$ is a general point on ${\widetilde{X}}$.
Therefore, by Riemann--Roch and adjunction we have
\begin{equation*}
\chi({\widetilde{{\mathfrak{E}}}}_{Z_2},{\widetilde{{\mathscr{F}}}}) = 
2\chi({\mathscr{O}}_{\widetilde{X}},{\widetilde{{\mathscr{F}}}}) + \chi(\omega_{\widetilde{X}}^{-1},{\widetilde{{\mathscr{F}}}}) - 3\chi({\mathscr{O}}_{\widetilde{P}},{\widetilde{{\mathscr{F}}}}) =
2\chi({\mathscr{O}}_X,{\mathscr{F}}) + \chi(\omega_X^{-1},{\mathscr{F}}) - 3\chi({\mathscr{O}}_{\pi({\widetilde{P}})},{\mathscr{F}}),
\end{equation*}
which gives the first equality.
Similarly, for ${\widetilde{{\mathfrak{E}}}}_{Z_3}$ we have
\begin{equation*}
\mathrm{ch}({\widetilde{{\mathfrak{E}}}}_{Z_3}) = \mathrm{ch}({\mathscr{O}}_{\widetilde{X}}(h)) + \mathrm{ch}({\mathscr{O}}_{\widetilde{X}}(2h - e_1 - e_2 - e_3)) = 
\mathrm{ch}({\mathscr{O}}_{\widetilde{X}}) + \mathrm{ch}(\omega_{\widetilde{X}}^{-1}) - 2\mathrm{ch}({\mathscr{O}}_{\widetilde{P}}),
\end{equation*}
and using Riemann--Roch and adjunction in the same way as before, we finish the proof.

For a sheaf ${\mathscr{F}}$ on $X$ we denote by 
\begin{equation*}
h_{\mathscr{F}}(t) := \chi({\mathscr{F}}(-tK_X)) \in {\mathbb{Z}}[t],
\end{equation*}
the Hilbert polynomial of ${\mathscr{F}}$ with respect to the anticanonical polarization of $X$.

\begin{equation}\label{eq:hd-inequalities}
h_4(t) > h_3(t) > h_2(t) > h_{{\mathscr{O}}_X}(t) > h_4(t-1) > h_3(t-1) > h_2(t-1)
\qquad\text{for all $t \gg 0$.}
\end{equation}

Let $S$ be an arbitrary base scheme and ${\mathscr{F}}$ a coherent sheaf on $X \times S$ flat over $S$ and such that 
for any geometric point $s \in S$ the restriction ${\mathscr{F}}_s = i_{X \times s}^*({\mathscr{F}})$ is a semistable (i.e., torsion free) sheaf with Hilbert polynomial~$h_d(t)$ for $d \in \{2,3\}$.
By Lemma~\ref{lemma:md-points} it follows that 
\begin{equation*}
{\mathscr{F}}_s \cong {\mathscr{E}}_z 
\end{equation*}
for a unique closed point $z \in Z_d$.

Consider the semiorthogonal decomposition
\begin{equation}\label{eq:dbx-s}
{\mathbf{D}}(X \times S) = \langle {\mathcal{A}}_{1S}, {\mathcal{A}}_{2S}, {\mathcal{A}}_{3S} \rangle = \langle {\mathbf{D}}(S), {\mathbf{D}}(Z_2 \times S), {\mathbf{D}}(Z_3 \times S) \rangle,
\end{equation}
obtained by the base change $S \to \mathrm{Spec}({\mathsf{k}})$ (\cite[Theorem~5.6]{kuznetsov2011base}) from~\eqref{eq:dbx-dz} 
(the second equality follows from \cite[Theorem~6.4]{kuznetsov2011base} and Proposition~\ref{proposition:fm-zd}).
Since by Proposition~\ref{proposition:fm-zd} the embedding functors of~\eqref{eq:dbx-dz} are the Fourier--Mukai functors given by the sheaves ${\mathscr{E}}_{Z_d}$,
the embedding functors of~\eqref{eq:dbx-s} are given by the pullbacks ${\mathscr{E}}_{Z_d} \boxtimes {\mathscr{O}}_S$ of ${\mathscr{E}}_{Z_d}$ via the maps $X \times Z_d \times S \to X \times Z_d$.

For any ${\mathscr{F}} \in {\mathbf{D}}(X \times S)$, a geometric point $s \in S$, and each $d' \in \{1,2,3\}$ we have by~\cite[(11)]{kuznetsov2011base} an isomorphism
\begin{equation*}
i_{Z_{d'} \times s}^*(\alpha_{d'S}({\mathscr{F}})) \cong \alpha_{d'}(i_{X \times s}^*({\mathscr{F}})) \in {\mathbf{D}}(Z_{d'}),
\end{equation*}
where $\alpha_{d'} \colon {\mathbf{D}}(X) \to {\mathbf{D}}(Z_{d'})$ and $\alpha_{d'S} \colon {\mathbf{D}}(X \times S) \to {\mathbf{D}}(Z_{d'} \times S)$ are 
the projection functors of the semiorthogonal decompositions~\eqref{eq:dbx-dz} and~\eqref{eq:dbx-s} respectively.
Using this isomorphism for the sheaf~${\mathscr{F}}$ we started with, and taking into account Lemma~\ref{lemma:e-z-small}, we conclude that
\begin{equation*}
i_{Z_{d'} \times s}^*(\alpha_{d'S}({\mathscr{F}})) \cong \alpha_{d'}({\mathscr{F}}_s) \cong \alpha_{d'}({\mathscr{E}}_z) \cong 
\begin{cases}
{\mathscr{O}}_z, & \text{if $d' = d$},\\
0, & \text{otherwise}.
\end{cases}
\end{equation*} 
By Lemma~\ref{lemma:fiberwise}$(i)$ it follows that $\alpha_{d'S}({\mathscr{F}}) = 0$ when $d' \ne d$, hence 
\begin{equation*}
{\mathscr{F}} \cong \Phi_{{\mathscr{E}}_{Z_d} \boxtimes {\mathscr{O}}_S}({\mathscr{F}}_d)
\end{equation*}
for some object ${\mathscr{F}}_d \in {\mathbf{D}}(Z_d \times S)$.
Moreover, the object ${\mathscr{F}}_d$ is such that for any geometric point~$s \in S$ we have  $i_{Z_d \times s}^*({\mathscr{F}}_d) \cong {\mathscr{O}}_z$ for some closed point~$z \in Z_d$.
By Lemma~\ref{lemma:fiberwise}$(iii)$ it follows that ${\mathscr{F}}_d \cong \Gamma_{f_d*}{\mathscr{L}}$, where $f_d \colon S \to Z_d$ is a morphism, $\Gamma_{f_d} \colon S \to Z_d \times S$ is its graph, and ${\mathscr{L}}$ is a line bundle on $S$.
Therefore
\begin{equation*}
{\mathscr{F}} \cong \Phi_{{\mathscr{E}}_{Z_d} \boxtimes {\mathscr{O}}_S}(\Gamma_{f_d*}{\mathscr{L}}) 
\cong (\mathrm{id}_X \times f_d)^*{\mathscr{E}}_{Z_d} \otimes p_S^*{\mathscr{L}}.
\end{equation*}
This precisely means that the moduli functor ${\mathscr{M}}_d(X)$ we are interested in is represented by the scheme~$Z_d$, 
and that ${\mathscr{E}}_{Z_d}$ is a universal sheaf.

This proves the statement about~${\mathscr{M}}_2(X)$ and the first statement about~${\mathscr{M}}_3(X)$.
The same argument applied to the dual semiorthogonal decomposition~\eqref{eq:dbx-dual} instead of~\eqref{eq:dbx-dz} 
proves the statement about~${\mathscr{M}}_4(X)$ and the second statement about~${\mathscr{M}}_3(X)$.

\label{lemma:oc-decomposition}
$(i)$ If $C \subset X$ is a curve with Hilbert polynomial $h'_d(t)$ with $d \in \{2,3\}$ then there is a unique closed point $z \in Z_d$ and an exact sequence
\begin{equation*}
0 \to {\mathscr{E}}_z^\vee \to {\mathscr{O}}_X \to {\mathscr{O}}_C \to 0.
\end{equation*}
Conversely, any nonzero morphism ${\mathscr{E}}_z^\vee \to {\mathscr{O}}_X$ is injective with cokernel isomorphic to ${\mathscr{O}}_C$.

$(ii)$ Similarly, if $L \subset X$ is a line, i.e., a curve with Hilbert polynomial $h'_1(t)$ then there are unique closed points $z_2 \in Z_2$ and $z_3 \in Z_3$ and an exact sequence
\begin{equation*}
0 \to {\mathscr{E}}_{z_2} \to {\mathscr{E}}_{z_3} \to {\mathscr{O}}_L \to 0.
\end{equation*}
Conversely, any nonzero morphism ${\mathscr{E}}_{z_2} \to {\mathscr{E}}_{z_3}$ is injective with cokernel isomorphic to ${\mathscr{O}}_L$.

If $C \subset X$ is a curve with Hilbert polynomial $h'_d(t)$ with $d \in \{2,3\}$ then there is a unique closed point $z \in Z_d$ and an exact sequence
\begin{equation*}
0 \to {\mathscr{E}}_z^\vee \to {\mathscr{O}}_X \to {\mathscr{O}}_C \to 0.

For the first part of~$(i)$, by Lemma~\ref{lemma:md-points}$(ii)$ it is enough to show 
that $I_C \otimes \omega_X^{-1}$ is stable with Hilbert polynomial~$h_{6-d}(t)$.
Stability is clear by Lemma~\ref{lemma:hd-stable}, and the Hilbert polynomial evidently equals 
\begin{equation*}
h_{{\mathscr{O}}_X}(t+1) - h'_d(t+1) = (3(t+1)(t+2) + 1) - (d(t+1) + 1) = (3t + 6 - d)(t + 1) = h_{6-d}(t).
\end{equation*}



For the first part of~$(ii)$ first note that by Serre duality 
\begin{equation*}
\mathrm{Ext}^\bullet({\mathscr{O}}_L,{\mathscr{O}}_X) \cong \mathrm{Ext}^\bullet({\mathscr{O}}_X,{\mathscr{O}}_L(K_X))^\vee = H^\bullet(L,{\mathscr{O}}_L(-1)) = 0 
\end{equation*}
since $L \cong {\mathbb{P}}^1$ and $L \cdot K_X = -1$.
Thus by Theorem~\ref{theorem:dbx} the structure sheaf ${\mathscr{O}}_L$ is contained in the subcategory~$\langle {\mathcal{A}}_2, {\mathcal{A}}_3 \rangle$ of ${\mathbf{D}}(X)$.
Next, again by Serre duality
\begin{equation*}
\mathrm{Ext}^i({\mathscr{O}}_L,{\mathfrak{E}}_{Z_2}) \cong \mathrm{Ext}^{2-i}({\mathfrak{E}}_{Z_2},{\mathscr{O}}_L(K_X))^\vee.
\end{equation*}
Since ${\mathfrak{E}}_{Z_2}$ is a vector bundle and $L$ is a curve, the right hand side is zero unless $i \in \{1, 2\}$.
On the other hand, ${\mathfrak{E}}_{Z_2}$ is globally generated by Proposition~\ref{proposition:e-z-big} and~\eqref{eq:cezd}, while ${\mathscr{O}}_L(K_X) \cong {\mathscr{O}}_L(-1)$ has no global sections, hence for $i = 2$ the right hand side is also zero.
On the other hand, by Lemma~\ref{lemma:chi-ez-f} we have
\begin{equation*}
\chi({\mathfrak{E}}_{Z_2},{\mathscr{O}}_L(K_X)) = 2\chi(X,{\mathscr{O}}_L(K_X)) + \chi(X,{\mathscr{O}}_L(2K_X)) - 3r({\mathscr{O}}_L(K_X)) = 2 \cdot h'_1(-1) + h'_1(-2) = -1,
\end{equation*}
and we conclude that $\mathrm{Ext}^\bullet({\mathscr{O}}_L, {\mathfrak{E}}_{Z_2}) = {\mathsf{k}}[-1]$.
This means that there is a unique closed point $z_2 \in Z_2$ and a unique extension
\begin{equation*}
0 \to {\mathscr{E}}_{z_2} \to {\mathscr{F}} \to {\mathscr{O}}_L \to 0
\end{equation*}
such that ${\mathscr{F}} \in {\mathcal{A}}_3$. 
It remains to note that ${\mathscr{F}}$ is a sheaf of rank 1, hence there is a unique $z_3 \in Z_3$ such that ${\mathscr{F}} \cong {\mathscr{E}}_{z_3}$.

The converse statements are evident.

\label{proposition:fd-zd}
We have natural isomorphisms of Hilbert schemes
\begin{equation*}
F_1(X) \cong Z_2 \times Z_3,
\qquad
F_2(X) \cong {\mathbb{P}}_{Z_2}(p_{2*}{\mathscr{E}}_{Z_2}),
\qquad\text{and}\qquad 
F_3(X) \cong {\mathbb{P}}_{Z_3}(p_{3*}{\mathscr{E}}_{Z_3}).
\end{equation*}

Assume $d \in \{2,3\}$.
Let ${\mathscr{C}} \subset X \times S$ be a flat $S$-family of subschemes in $X$ with Hilbert polynomial~$h'_d(t)$.
Consider the decomposition of the structure sheaf ${\mathscr{O}}_{\mathscr{C}} \in {\mathbf{D}}(X \times S)$ with respect to the semiorthogonal decomposition 
\begin{equation*}
{\mathbf{D}}(X \times S) = \langle {\mathcal{A}}_{3S}^\vee, {\mathcal{A}}_{2S}^\vee, {\mathcal{A}}_{1S}^\vee \rangle,
\end{equation*}
obtained from the decomposition of Proposition~\ref{proposition:dbx-dual} 
by the base change $S \to \mathrm{Spec}({\mathsf{k}})$ via~\cite[Theorem~5.6]{kuznetsov2011base}.
The argument of Theorem~\ref{theorem:moduli} together with the result of Lemma~\ref{lemma:oc-decomposition}$(i)$ shows 
that there is a morphism $f_d \colon S \to Z_d$, a line bundle ${\mathscr{F}}_d$ on $S$, and an exact sequence
\begin{equation*}
0 \to (\mathrm{id}_X \times f_d)^*({\mathscr{E}}_{Z_d}^\vee) \otimes p_S^*({\mathscr{F}}_d) \to {\mathscr{O}}_{X \times S} \to {\mathscr{O}}_{\mathscr{C}} \to 0
\end{equation*}
The left arrow corresponds to a global section of the bundle $(\mathrm{id}_X \times f_d)^*({\mathscr{E}}_{Z_d}) \otimes p_S^*({\mathscr{F}}_d^\vee)$, i.e., to a morphism from $p_S^*{\mathscr{F}}_d$ to $(\mathrm{id}_X \times f_d)^*({\mathscr{E}}_{Z_d})$.
We have 
\begin{equation*}
\mathrm{Hom}(p_S^*{\mathscr{F}}_d,(\mathrm{id}_X \times f_d)^*({\mathscr{E}}_{Z_d})) \cong
\mathrm{Hom}({\mathscr{F}}_d,p_{S*}((\mathrm{id}_X \times f_d)^*({\mathscr{E}}_{Z_d}))) \cong
\mathrm{Hom}({\mathscr{F}}_d,f_d^*p_{d*}({\mathscr{E}}_{Z_d})),
\end{equation*}
where the first equality follows from adjunction and the second is the base change for the diagram
\begin{equation*}
\xymatrix@C=5em{
X \times S \ar[r]^-{\mathrm{id}_X \times f_d} \ar[d]_{p_S} & X \times Z_d \ar[d]^{p_d} \\
S \ar[r]^-{f_d} & Z_d
}
\end{equation*}
The flatness over $S$ of the cokernel ${\mathscr{O}}_{\mathscr{C}}$ of the morphism $(\mathrm{id}_X \times f_d)^*({\mathscr{E}}_{Z_d}^\vee) \otimes p_S^*({\mathscr{F}}_d) \to {\mathscr{O}}_{X \times S}$ 
is equivalent to the corresponding morphism ${\mathscr{F}}_d \to f_d^*p_{d*}{\mathscr{E}}_{Z_d}$ being nonzero for every closed point $s \in S$.
Thus the Hilbert scheme functor $F_d(X)$ is isomorphic to the functor that associates to a scheme $S$ a morphism $f_d \colon S \to Z_d$ and a line subbundle in $f_d^*p_{d*}{\mathscr{E}}_{Z_d}$, 
hence is represented by the projective bundle ${\mathbb{P}}_{Z_d}(p_{d*}{\mathscr{E}}_{Z_d})$.

Now assume $d = 1$ and let ${\mathscr{C}} \subset X \times S$ be a flat family of lines.
Decomposing ${\mathscr{O}}_{\mathscr{C}}$ with respect to~\eqref{eq:dbx-s} 
and using the argument of Theorem~\ref{theorem:moduli} together with the result of Lemma~\ref{lemma:oc-decomposition}$(ii)$,
we conclude that there are morphisms $f_2 \colon S \to Z_2$ and $f_3 \colon S \to Z_3$,
line bundles ${\mathscr{F}}_2$ and ${\mathscr{F}}_3$ on $S$, and an exact sequence
\begin{equation}\label{eq:o-lines}
0 \to (\mathrm{id}_X \times f_{2})^*({\mathscr{E}}_{Z_2}) \otimes p_S^*({\mathscr{F}}_2) \to (\mathrm{id}_X \times f_{3})^*({\mathscr{E}}_{Z_3}) \otimes p_S^*({\mathscr{F}}_3) \to {\mathscr{O}}_{\mathscr{C}} \to 0.
\end{equation}
Moreover, the pushforward to $S$ of this sequence gives (again by base change) an exact sequence
\begin{equation*}
0 \to f_{2}^*(p_{2*}{\mathscr{E}}_{Z_2}) \otimes {\mathscr{F}}_2 \to f_{3}^*(p_{3*}{\mathscr{E}}_{Z_3}) \otimes {\mathscr{F}}_3 \to {\mathscr{O}}_S \to 0.
\end{equation*}
Since by Lemma~\ref{lemma:ps-ez} we know that $f_{d}^*(p_{d*}{\mathscr{E}}_{Z_d})$ is a vector bundle of rank $d$ on $S$, the comparison of determinants gives  a relation
\begin{equation}\label{eq:f23-relation}
{\mathscr{F}}_3^3 \otimes {\mathscr{F}}_2^{-2} \cong f_{2}^*(\det(p_{2*}{\mathscr{E}}_{Z_2})) \otimes f_{3}^*(\det(p_{3*}{\mathscr{E}}_{Z_3})^{-1}).
\end{equation}
Denoting by $f_{23} \colon S \to Z_2 \times Z_3$ the map induced by $f_2$ and $f_3$, we deduce by adjunction and base change 
\begin{equation*}
\mathrm{Hom}(f_{2}^*(p_{2*}{\mathscr{E}}_{Z_2}) \otimes {\mathscr{F}}_2, f_{3}^*(p_{3*}{\mathscr{E}}_{Z_3}) \otimes {\mathscr{F}}_3) \cong

\mathrm{Hom}({\mathscr{F}}_2 \otimes {\mathscr{F}}_3^\vee,f_{23}^*p_{23*}(p_{X2}^*{\mathscr{E}}_{Z_2}^\vee \otimes p_{X3}^*{\mathscr{E}}_{Z_3}))
\end{equation*}
and note that $f_{23}^*p_{23*}(p_{X2}^*{\mathscr{E}}_{Z_2}^\vee \otimes p_{X3}^*{\mathscr{E}}_{Z_3})$ is a line bundle (again by Lemma~\ref{lemma:ps-ez}).
The flatness over~$S$ of the cokernel ${\mathscr{O}}_{\mathscr{C}}$ of the morphism of~\eqref{eq:o-lines} is equivalent to the pointwise injectivity 
of the corresponding morphism ${\mathscr{F}}_2 \otimes {\mathscr{F}}_3^\vee \to f_{23}^*p_{23*}(p_{X2}^*{\mathscr{E}}_{Z_2}^\vee \otimes p_{X3}^*{\mathscr{E}}_{Z_3})$,
i.e., to this map being an isomorphism.
On the other hand, any line bundle on $S$ can be written as the tensor product of line bundles ${\mathscr{F}}_2 \otimes {\mathscr{F}}_3^\vee$ satisfying~\eqref{eq:f23-relation} in a unique way.
This shows that the Hilbert scheme functor is isomorphic to the functor that associates to a scheme $S$ a pair of morphisms $f_2 \colon S \to Z_2$ and $f_3 \colon S \to Z_3$,
hence is represented by $Z_2 \times Z_3$.

\begin{equation*}
\xymatrix@C=5em{
X \times S \ar[r]^-{\mathrm{id}_X \times f_d} \ar[d]_{p_S} & X \times Z_d \ar[d]^{p_d} \\
S \ar[r]^-{f_d} & Z_d
}
\end{equation*}

\label{remark:f4}
With the same argument one can prove that $p_{2*}({\mathscr{E}}_{Z_2}^\vee \otimes \omega_X^{-1})$ is a rank-4 vector bundle on~$Z_2$ 
and that~$F_4(X) \cong {\mathbb{P}}_{Z_2}(p_{2*}({\mathscr{E}}_{Z_2}^\vee \otimes \omega_X^{-1}))$.

\label{definition:family-dp6}
A family $f \colon {\mathscr{X}} \to S$ is a {\sf du Val family} of sextic del Pezzo surfaces, if $f$ is a flat projective morphism such that 
for every geometric point $s \in S$ the fiber ${\mathscr{X}}_s$ of ${\mathscr{X}}$ over $s$ is a sextic du Val del Pezzo surface (Definition~\ref{definition:dp6}), 
i.e., a normal integral surface with at worst du Val singularities such that $-K_{{\mathscr{X}}_s}$ is an ample Cartier divisor and $K_{{\mathscr{X}}_s}^2 = 6$.

\label{theorem:sod-dp6}
Assume $f \colon {\mathscr{X}} \to S$ is a du Val family of sextic del Pezzo surfaces.
Then there is an~$S$-linear semiorthogonal decomposition \textup{(}compatible with any base change\textup{)}
\begin{equation}
\label{eq:sod-dp6}
{\mathbf{D}}({\mathscr{X}}) = \langle {\mathbf{D}}(S), {\mathbf{D}}({\mathscr{Z}}_2,\beta_{{\mathscr{Z}}_2}), {\mathbf{D}}({\mathscr{Z}}_3,\beta_{{\mathscr{Z}}_3}) \rangle,
\end{equation}
where ${\mathscr{Z}}_2 \to S$ and ${\mathscr{Z}}_3 \to S$ are finite flat morphisms of degree $3$ and $2$ respectively, 
$\beta_{{\mathscr{Z}}_2}$ and $\beta_{{\mathscr{Z}}_3}$ are Brauer classes of order $2$ and $3$ respectively on them,
and the last two components are the twisted derived categories.

\label{proposition:md-zd}
For $d \in \{2,3,4\}$ the stack ${\mathscr{M}}_d({\mathscr{X}}/S)$ is a ${\mathrm{G}_{\mathrm{m}}}$-gerbe over its coarse module space 
\begin{equation*}
{\mathscr{Z}}_d({\mathscr{X}}/S) := ({\mathscr{M}}_d({\mathscr{X}}/S))_{\mathrm{coarse}}
\end{equation*}
with an obstruction given by a Brauer class $\beta_{{\mathscr{Z}}_d({\mathscr{X}}/S)}$ of order
\begin{equation}
\label{eq:brauer-order}
\operatorname{ord} \beta_{{\mathscr{Z}}_d({\mathscr{X}}/S)} = 
\begin{cases}
2, & \text{if $d = 2$ or $d = 4$},\\
3, & \text{if $d = 3$}.
\end{cases}
\end{equation}
Moreover, there is an isomorphism of the coarse moduli spaces $\sigma_{2,4} \colon {\mathscr{Z}}_4({\mathscr{X}}/S) \xrightarrow{\ \sim\ } {\mathscr{Z}}_2({\mathscr{X}}/S)$ and
an automorphism $\sigma_{3,3} \colon {\mathscr{Z}}_3({\mathscr{X}}/S) \xrightarrow{\ \sim\ } {\mathscr{Z}}_3({\mathscr{X}}/S)$, 
such that 
\begin{equation*}
\beta_{{\mathscr{Z}}_4({\mathscr{X}}/S)} = \sigma_{2,4}^*(\beta_{{\mathscr{Z}}_2({\mathscr{X}}/S)}^{-1}) = \sigma_{2,4}^*(\beta_{{\mathscr{Z}}_2({\mathscr{X}}/S)})
\qquad\text{and}\qquad
\beta_{{\mathscr{Z}}_3({\mathscr{X}}/S)} = \sigma_{3,3}^*(\beta_{{\mathscr{Z}}_3({\mathscr{X}}/S)}^{-1}).
\end{equation*}

Note that the relation between the quasiuniversal families discussed in Proposition~\ref{proposition:md-zd} in terms of twisted universal families means that
there are line bundles ${\mathscr{L}}_{2,4}$ and ${\mathscr{L}}_{3,3}$ on ${\mathscr{Z}}_4({\mathscr{X}}/S)$ and ${\mathscr{Z}}_3({\mathscr{X}}/S)$ respectively, such that
\begin{equation*}
{\mathscr{E}}_{{\mathscr{Z}}_4({\mathscr{X}}/S)} = \sigma_{2,4}^*({\mathscr{E}}_{{\mathscr{Z}}_2({\mathscr{X}}/S)}^{\vee} \otimes \omega_{{\mathscr{X}}/S}^{-1}) \otimes {\mathscr{L}}_{2,4}
\qquad\text{and}\qquad
{\mathscr{E}}_{{\mathscr{Z}}_3({\mathscr{X}}/S)} = \sigma_{3,3}^*({\mathscr{E}}_{{\mathscr{Z}}_3({\mathscr{X}}/S)}^{\vee} \otimes \omega_{{\mathscr{X}}/S}^{-1}) \otimes {\mathscr{L}}_{3,3}.
\end{equation*}

\label{lemma:md-zd-base-change}
Let $\phi \colon S' \to S$ be a base change and denote ${\mathscr{X}}' := {\mathscr{X}} \times_S S'$.
We have
\begin{equation}
\label{eq:md-zd-base-change}
{\mathscr{M}}_d({\mathscr{X}}'/S') \cong {\mathscr{M}}_d({\mathscr{X}}/S) \times_S S'
\qquad\text{and}\qquad
{\mathscr{Z}}_d({\mathscr{X}}'/S') \cong {\mathscr{Z}}_d({\mathscr{X}}/S) \times_S S'.
\end{equation} 
Moreover, isomorphisms~\eqref{eq:md-zd-base-change} are compatible with the universal families, i.e., 
\begin{equation}\label{eq:ced-base-change}
\beta_{{\mathscr{Z}}'_d} = \phi_{{\mathscr{Z}}_d}^*(\beta_{{\mathscr{Z}}_d})
\qquad\text{and}\qquad
{\mathscr{E}}_{{\mathscr{Z}}'_d} \cong \phi_{{\mathscr{X}} \times_S {\mathscr{Z}}_d}^*{\mathscr{E}}_{{\mathscr{Z}}_d}.
\end{equation}
where we set ${\mathscr{Z}}'_d := {\mathscr{Z}}_d({\mathscr{X}}'/S')$ and denote the morphisms induced by the base change
by $\phi_{\mathscr{X}} \colon {\mathscr{X}}' \to {\mathscr{X}}$, $\phi_{{\mathscr{Z}}_d} \colon {\mathscr{Z}}'_d \to {\mathscr{Z}}_d$, 
and $\phi_{{\mathscr{X}} \times_S {\mathscr{Z}}_d} \colon {\mathscr{X}}' \times_{S'} {\mathscr{Z}}'_d \to {\mathscr{X}} \times_S {\mathscr{Z}}_d$, respectively.

\label{corollary:S-s}
For any geometric point $s \in S$ there are isomorphisms
\begin{equation}
\label{eq:m-z-e-s}
{\mathscr{M}}_d({\mathscr{X}}/S)_s \cong {\mathscr{M}}_d(X),
\qquad
{\mathscr{Z}}_d({\mathscr{X}}/S)_s \cong Z_d
\qquad\text{and}\qquad
i_{Z_d}^*({\mathscr{E}}_{{\mathscr{Z}}_d}) \cong {\mathscr{E}}_{Z_d},
\end{equation}
where $X = {\mathscr{X}}_s$ is the fiber of ${\mathscr{X}}$ over $s$ and $i_{Z_d} \colon Z_d \cong {\mathscr{Z}}_d({\mathscr{X}}/S)_s \hookrightarrow {\mathscr{Z}}_d({\mathscr{X}}/S)$ 
is the natural embedding.

\label{lemma:zd-flat}
The maps $f_2 \colon {\mathscr{Z}}_2 \to S$ and $f_3 \colon {\mathscr{Z}}_3 \to S$ are finite flat maps of degree $3$ and $2$ respectively.
The relative dualizing complexes $\omega_{{\mathscr{Z}}_2/S}^\bullet$ and $\omega_{{\mathscr{Z}}_3/S}^\bullet$ are line bundles.

we have a fiber square
\begin{equation}
\label{diagram:x-s-z}
\vcenter{\xymatrix@C=5em{
{\mathscr{X}} \times_S {\mathscr{Z}}_d \ar[r]^{p_d} \ar[d]_{p} 
& {\mathscr{Z}}_d \ar[d]^{f_d} \\
{\mathscr{X}} \ar[r]_-f & S
}}
\end{equation}

\label{lemma:phi-d-shriek}
The functor $\Phi_d$ is $S$-linear, preserves boundedness and perfectness, and its right adjoint functor is
\begin{equation}
\label{eq:phid-shriek}
\Phi_d^! \colon {\mathbf{D}}({\mathscr{X}}) \to {\mathbf{D}}({\mathscr{Z}}_d,\beta_{{\mathscr{Z}}_d}),\qquad
\Phi_d^!({\mathscr{G}}) \cong p_{d*}\mathrm{R}\mathscr{H}\mathit{om}({\mathscr{E}}_{{\mathscr{Z}}_d},p^!{\mathscr{G}}).
\end{equation}

\label{lemma:phid-shriek-other}
We have an isomorphism of functors
\begin{equation*}
\Phi_d^!({\mathscr{G}}) \cong p_{d*}({\mathscr{E}}_{{\mathscr{Z}}_d}^\vee \otimes p_d^*\omega_{{\mathscr{Z}}_d/S} \otimes p^*({\mathscr{G}})),
\end{equation*}
where ${\mathscr{E}}_{{\mathscr{Z}}_d}^\vee := \mathrm{R}\mathscr{H}\mathit{om}({\mathscr{E}}_{{\mathscr{Z}}_d},{\mathscr{O}}_{{\mathscr{X}} \times_S {\mathscr{Z}}_d})$ is a coherent sheaf flat over ${\mathscr{Z}}_d$.
The kernel~${\mathscr{E}}_{{\mathscr{Z}}_d}^\vee \otimes p_d^*\omega_{{\mathscr{Z}}_d/S}$ of this functor is compativle with base changes, i.e.,
if $\phi \colon S' \to S$ is a base change, then
\begin{equation*}
\phi_{{\mathscr{X}} \times_S {\mathscr{Z}}_d}^*({\mathscr{E}}_{{\mathscr{Z}}_d}^\vee \otimes p_d^*\omega_{{\mathscr{Z}}_d/S}) \cong {\mathscr{E}}_{{\mathscr{Z}}'_d}^\vee \otimes p_d^{\prime*}\omega_{{\mathscr{Z}}'_d/S'}.
\end{equation*}

We have an isomorphism of functors
\begin{equation*}
\Phi_d^!({\mathscr{G}}) \cong p_{d*}({\mathscr{E}}_{{\mathscr{Z}}_d}^\vee \otimes p_d^*\omega_{{\mathscr{Z}}_d/S} \otimes p^*({\mathscr{G}})),
\end{equation*}

For a Fourier--Mukai functor compatibilities with base changes are proved in~\cite[Lemma~2.42]{kuznetsov2006hyperplane}
(the assumption of finiteness of $\mathrm{Tor}$-dimension of the base change morphism is only used in the second half of that lemma).
It remains to note that both $\Phi_d$ and $\Phi_d^!$ are Fourier--Mukai functors (the first by definition~\eqref{eq:phid-definition} and the second by Lemma~\ref{lemma:phid-shriek-other}).

Take $d_1,d_2 \in \{1,2,3\}$ and consider the diagram
\begin{equation*}
\xymatrix{
& {\mathscr{Z}}_{d_1} \times_S {\mathscr{X}} \times_S {\mathscr{Z}}_{d_2} 
\ar[dl]_{\mathrm{pr}_{1,2}} \ar[d]^{\mathrm{pr}_{1,3}} \ar[dr]^{\mathrm{pr}_{2,3}} \\
{\mathscr{Z}}_{d_1} \times_S {\mathscr{X}} & {\mathscr{Z}}_{d_1} \times_S {\mathscr{Z}}_{d_2} & {\mathscr{X}} \times_S {\mathscr{Z}}_{d_2} 
}
\end{equation*}
A standard computation shows that the composition of functors $\Phi_{d_2}^! \circ \Phi_{d_1}$ is a Fourier--Mukai functor given by the object
\begin{equation}
\label{eq:convolution}
\mathrm{pr}_{1,3*}(\mathrm{pr}_{2,3}^*({\mathscr{E}}_{{\mathscr{Z}}_{d_2}}^\vee \otimes p_{d_2}^*\omega_{{\mathscr{Z}}_{d_2}/S}) \otimes \mathrm{pr}_{1,2}^*({\mathscr{E}}_{{\mathscr{Z}}_{d_1}})) \in {\mathbf{D}}({\mathscr{Z}}_{d_1} \times_S {\mathscr{Z}}_{d_2}, \beta_{{\mathscr{Z}}_{d_1}}^{-1} \boxtimes \beta_{{\mathscr{Z}}_{d_2}}).
\end{equation}

Let us prove that $\Phi_d$ is fully faithful for each $d \in \{1,2,3\}$.
For this it is enough to check that the object~\eqref{eq:convolution} in case $d_1 = d_2 = d$ is isomorphic 
(via the unit of adjunction morphism) to the structure sheaf of the diagonal.
Since the unit of the adjunction is induced by a morphism of kernels \cite{anno2012adjunction}, 
by Lemma~\ref{lemma:fiberwise} it is enough to check that for any geometric point $s \in S$ we have
\begin{equation}
\label{eq:isomorphism-diagonal}
i_{Z_d \times Z_d}^*(\mathrm{pr}_{1,3*}(\mathrm{pr}_{2,3}^*({\mathscr{E}}_{{\mathscr{Z}}_{d}}^\vee \otimes p_{d}^*\omega_{{\mathscr{Z}}_{d}/S}) \otimes \mathrm{pr}_{1,2}^*({\mathscr{E}}_{{\mathscr{Z}}_{d}}))) \cong \delta_*{\mathscr{O}}_{Z_d} \in {\mathbf{D}}(Z_d \times Z_d)
\end{equation}
where $i_{Z_d \times Z_d} \colon Z_d \times Z_d \to {\mathscr{Z}}_d \times_S {\mathscr{Z}}_d$ is the natural embedding 
and $\delta \colon Z_d \to Z_d \times Z_d$ is the diagonal.
Using base change and isomorphisms of Lemma~\ref{lemma:md-zd-base-change} and Lemma~\ref{lemma:phid-shriek-other}, 
we can rewrite the left hand side of~\eqref{eq:isomorphism-diagonal} as the Fourier--Mukai kernel of the functor
\begin{equation*}
{\mathbf{D}}(Z_d) \xrightarrow{\ \Phi_{{\mathscr{E}}_{Z_d}}\ } {\mathbf{D}}(X) \xrightarrow{\ \Phi_{{\mathscr{E}}_{Z_d}}^!\ } {\mathbf{D}}(Z_d),
\end{equation*}
where the functor $\Phi_{{\mathscr{E}}_{Z_d}}$ is identified in Proposition~\ref{proposition:fm-zd} 
with the equivalence ${\mathbf{D}}(Z_d) \cong {\mathcal{A}}_d \subset {\mathbf{D}}(X)$, and~$\Phi_{{\mathscr{E}}_{Z_d}}^!$ is its right adjoint.
This composition is isomorphic to the identity, since the functor $\Phi_{{\mathscr{E}}_{Z_d}}$ is fully faithful, 
hence we have~\eqref{eq:isomorphism-diagonal}.
Therefore, the functor $\Phi_d$ is fully faithful.





Next, let us prove that the subcategories $\Phi_d({\mathbf{D}}({\mathscr{Z}}_d,\beta_{{\mathscr{Z}}_d})) \subset {\mathbf{D}}({\mathscr{X}})$ for $1 \le d \le 3$ are semiorthogonal.
For this it is enough to check that the object~\eqref{eq:convolution} in case $d_1 < d_2$ is zero.
Again, using Lemma~\ref{lemma:fiberwise} and base change isomorphisms of Lemma~\ref{lemma:md-zd-base-change} 
and Lemma~\ref{lemma:phid-shriek-other} we reduce to the case of $S = \mathrm{Spec}({\mathsf{k}})$ with algebraically closed ${\mathsf{k}}$.
In the latter case, the required vanishing follows from semiorthogonality of the subcategories 
$\Phi_{{\mathscr{E}}_{Z_{d_i}}}({\mathbf{D}}(Z_{d_i})) = {\mathcal{A}}_{d_i}$ in ${\mathbf{D}}(X)$.


Finally, let us prove that the subcategories $\Phi_d({\mathbf{D}}({\mathscr{Z}}_d,\beta_{{\mathscr{Z}}_d})) \subset {\mathbf{D}}({\mathscr{X}})$ for $1 \le d \le 3$ generate ${\mathbf{D}}({\mathscr{X}})$.
Take any ${\mathscr{G}} \in {\mathbf{D}}({\mathscr{X}})$ and set 
\begin{equation*}
{\mathscr{G}}_2 := \mathrm{Cone}(\Phi_3\Phi_3^!{\mathscr{G}} \to {\mathscr{G}}),
\qquad
{\mathscr{G}}_1 := \mathrm{Cone}(\Phi_2\Phi_2^!{\mathscr{G}}_2 \to {\mathscr{G}}_2),
\qquad\text{and}\qquad
{\mathscr{G}}_0 := \mathrm{Cone}(\Phi_1\Phi_1^!{\mathscr{G}}_1 \to {\mathscr{G}}_1).
\end{equation*}
From full faithfulness and semiorthogonality it easily follows that $\Phi_1^!({\mathscr{G}}_0) = \Phi_2^!({\mathscr{G}}_0) = \Phi_3^!({\mathscr{G}}_0) = 0$.
Then Lemma~\ref{lemma:phid-linear} implies that for any geometric point $s \in S$ setting ${\mathscr{G}}_{0s} = i_{X}^*({\mathscr{G}}_0) \in {\mathbf{D}}(X)$ to be the restriction of ${\mathscr{G}}_0$ to the fiber $X = {\mathscr{X}}_s$, 
we have $\Phi_d^!({\mathscr{G}}_{0s}) = 0$ for all $d$.
By semiorthogonal decomposition~\eqref{eq:dbx-dz} this means that ${\mathscr{G}}_{0s} = 0$.
Hence by Lemma~\ref{lemma:fiberwise}$(i)$ we have ${\mathscr{G}}_0 = 0$.
Thus we have a chain of morphisms
\begin{equation*}
{\mathscr{G}} =: {\mathscr{G}}_3 \to {\mathscr{G}}_2 \to {\mathscr{G}}_1 \to {\mathscr{G}}_0 = 0
\end{equation*}
with $\mathrm{Cone}({\mathscr{G}}_{d} \to {\mathscr{G}}_{d-1}) \in \Phi_d({\mathbf{D}}({\mathscr{Z}}_d,\beta_{{\mathscr{Z}}_d}))$, which proves the required semiorthogonal decomposition.

This semiorthogonal decomposition is $S$-linear since by Lemma~\ref{lemma:phi-d-shriek} its embedding functors~$\Phi_d$ are $S$-linear,

and its compatibility with base changes follows from~\cite[Theorem~6.4]{kuznetsov2011base} 
together with Lemma~\ref{lemma:phid-linear} and Lemma~\ref{lemma:md-zd-base-change}.

\label{proposition:sod-dp6-perfect-unbounded}
The components of the semiorthogonal decomposition~\eqref{eq:sod-dp6} are admissible and their projection functors have finite cohomological amplitude.
Moreover, the functors $\Phi_d$ preserve perfectness and induce a semiorthogonal decomposition
\begin{equation}
\label{eq:sod-dpx-perf}
{\mathbf{D}}^{\mathrm{perf}}({\mathscr{X}}) = \langle \Phi_1({\mathbf{D}}^{\mathrm{perf}}(S)), \Phi_2({\mathbf{D}}^{\mathrm{perf}}({\mathscr{Z}}_2,\beta_{{\mathscr{Z}}_2})), \Phi_3({\mathbf{D}}^{\mathrm{perf}}({\mathscr{Z}}_3,\beta_{{\mathscr{Z}}_3})) \rangle.
\end{equation}

The functor $\Phi_d$ has finite cohomological amplitude because the sheaf ${\mathscr{E}}_{{\mathscr{Z}}_d}$ is flat over ${\mathscr{Z}}_d$ by Lemma~\ref{lemma:ezd-tor-ext}
(in fact, since $p \colon {\mathscr{X}} \times_S {\mathscr{Z}}_d \to {\mathscr{X}}$ is finite, the functor $\Phi_d$ is exact).
The functor $\Phi_d^!$ has finite cohomological amplitude because the sheaf ${\mathscr{E}}_{{\mathscr{Z}}_d}$ has finite $\mathrm{Ext}$-amplitude over ${\mathscr{Z}}_d$ by Lemma~\ref{lemma:ezd-tor-ext}
(in fact, since $p_d \colon {\mathscr{X}} \times_S {\mathscr{Z}}_d \to {\mathscr{Z}}_d$ is flat of relative dimension 2, the cohomological amplitude of the functor $\Phi_d^!$ equals $(0,2)$).
Thus $\Phi_d \circ \Phi_d^!$ has finite cohomological amplitude.
Since the projection functors of~\eqref{eq:sod-dp6} can be expressed as combinations of these functors

(see the proof of Theorem~\ref{theorem:sod-dp6}), 
it follows that the projection functors also have finite cohomological amplitude.



To show that the components of~\eqref{eq:sod-dp6} are admissible, note that we have two more decompositions
\begin{equation}
\label{eq:more-sod-cx}
\begin{aligned}
{\mathbf{D}}({\mathscr{X}}) &= \langle {\mathbf{D}}({\mathscr{Z}}_3,\beta_{{\mathscr{Z}}_3}) \otimes \omega_{{\mathscr{X}}/S}, {\mathbf{D}}(S), {\mathbf{D}}({\mathscr{Z}}_2, \beta_{{\mathscr{Z}}_2}) \rangle,
\\
{\mathbf{D}}({\mathscr{X}}) &= \langle {\mathbf{D}}({\mathscr{Z}}_2, \beta_{{\mathscr{Z}}_2}) \otimes \omega_{{\mathscr{X}}/S}, {\mathbf{D}}({\mathscr{Z}}_3,\beta_{{\mathscr{Z}}_3}) \otimes \omega_{{\mathscr{X}}/S}, {\mathbf{D}}(S) \rangle.
\end{aligned}
\end{equation} 
Indeed, they can be established by the same argument as~\eqref{eq:sod-dp6} 
starting with the semiorthogonal decompositions~\eqref{eq:dbx-other} instead of~\eqref{eq:dbx}.
Since $\omega_{{\mathscr{X}}/S}$ is invertible, the two above decompositions together with~\eqref{eq:sod-dp6} 
prove admissibility of all components (each of them appears on the left in one decomposition and on the right in another).

The functors $\Phi_d$ preserve perfectness by Lemma~\ref{lemma:phi-d-shriek}.

It remains to prove~\eqref{eq:sod-dpx-perf}.
For this note that the functors $\Phi_d$ have left adjoints $\Phi_d^*$ because the components of~\eqref{eq:sod-dp6} are admissible.
Since the functors $\Phi_d$ commute with arbitrary direct sums, it follows from~\cite[Theorem~5.1]{neeman1996grothendieck}
that the functors $\Phi_d^*$ preserve perfectness.
Since the projection functors of~\eqref{eq:sod-dp6} can be expressed as combinations of $\Phi_d \circ \Phi_d^*$,
they preserve perfectness, hence a restriction of~\eqref{eq:sod-dp6} gives~\eqref{eq:sod-dpx-perf}.

Therefore, the relative duality functor 
\begin{equation*}
{\mathrm{D}}_{{\mathscr{X}}/S}({\mathscr{F}}) := \mathrm{R}\mathscr{H}\mathit{om}({\mathscr{F}} , f^*\omega_S^\bullet)
\end{equation*}

\label{proposition:sod-dual}
The relative duality functor gives a semiorthogonal decomposition
\begin{equation}
\label{eq:sod-dp6-dual}
{\mathbf{D}}({\mathscr{X}}) = \langle {\mathrm{D}}_{{\mathscr{X}}/S}({\mathbf{D}}({\mathscr{Z}}_3,\beta_{{\mathscr{Z}}_3})), {\mathrm{D}}_{{\mathscr{X}}/S}({\mathbf{D}}({\mathscr{Z}}_2,\beta_{{\mathscr{Z}}_2})), {\mathrm{D}}_{{\mathscr{X}}/S}({\mathbf{D}}(S)) \rangle,
\end{equation}
whose components are equivalent to ${\mathbf{D}}({\mathscr{Z}}_3,\beta_{{\mathscr{Z}}_3})$, ${\mathbf{D}}({\mathscr{Z}}_2,\beta_{{\mathscr{Z}}_2})$, and ${\mathbf{D}}(S)$ respectively.
Moreover, this decomposition is right mutation-dual to~\eqref{eq:sod-dp6}.

Since ${\mathrm{D}}_{{\mathscr{X}}/S}$ is an anti-autoequivalence, \eqref{eq:sod-dp6-dual} is a semiorthogonal decomposition.
Consider also the right mutation-dual decomposition
\begin{equation*}
{\mathbf{D}}({\mathscr{X}}) = \langle {\mathbb{L}}_1({\mathbb{L}}_2(\Phi_3({\mathbf{D}}({\mathscr{Z}}_3,\beta_{{\mathscr{Z}}_3}))), {\mathbb{L}}_1(\Phi_2({\mathbf{D}}({\mathscr{Z}}_2,\beta_{{\mathscr{Z}}_2}))), \Phi_1({\mathbf{D}}(S)) \rangle,
\end{equation*}
where ${\mathbb{L}}_1$ and ${\mathbb{L}}_2$ are the mutation functors through the first and the second components of~\eqref{eq:dbcx-again} 
(they are well-defined because the components of the decomposition are admissible).
By base change together with Proposition~\ref{proposition:dbx-dual} and Lemma~\ref{lemma:fiberwise}, these two decompositions coincide.
In particular, the components of~\eqref{eq:sod-dp6-dual} are equivalent 
to ${\mathbf{D}}({\mathscr{Z}}_3,\beta_{{\mathscr{Z}}_3})$, ${\mathbf{D}}({\mathscr{Z}}_2,\beta_{{\mathscr{Z}}_2})$, and ${\mathbf{D}}(S)$ respectively.

\label{proposition:smoothness}
Let ${\mathscr{X}} \to S$ be a du Val family of sextic del Pezzo surfaces.
The total space ${\mathscr{X}}$ of the family is regular if and only if all three schemes $S$, ${\mathscr{Z}}_2$ and ${\mathscr{Z}}_3$ are regular.

\label{remark:smoothness}
Note also that a du Val family of sextic del Pezzo surfaces ${\mathscr{X}} \to S$ is smooth over $S$ 
if and only if the maps ${\mathscr{Z}}_2 \to S$ and ${\mathscr{Z}}_3 \to S$ are smooth (i.e.\ unramified).
Indeed, this follows from Corollary~\ref{corollary:S-s} 

and the description of the fibers~$Z_d$ of ${\mathscr{Z}}_d \to S$ in Corollary~\ref{corollary:dbx-z2-z3}.

We denote by $W_1$ and $W_2$ a pair of vector spaces of dimension 3 and let 
\begin{equation*}
{\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2) \hookrightarrow {\mathbb{P}}(W_1 \otimes W_2)
\end{equation*}
be the Segre embedding.

We denote by $K^\perp \subset W_1 \otimes W_2$ its codimension 2 annihilator, and set
\begin{equation}\label{eq:xk}
X_K := ({\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)) \cap {\mathbb{P}}(K^\perp) \subset {\mathbb{P}}(W_1 \otimes W_2), 
\end{equation}
to be the corresponding linear section.

\label{lemma:xk-duval}
Assume the base field ${\mathsf{k}}$ is algebraically closed.
The intersection $X_K$ defined by~\textup{\eqref{eq:xk}} is a sextic du Val del Pezzo surface if and only if 
\begin{itemize}
\item the line ${\mathbb{P}}(K)$ does not intersect the dual Segre variety ${\mathbb{P}}(W_1^\vee) \times {\mathbb{P}}(W_2^\vee) \subset {\mathbb{P}}(W_1^\vee \otimes W_2^\vee)$, and
\item the line ${\mathbb{P}}(K)$ is not contained in the discriminant cubic hypersurface ${\mathscr{D}}_{W_1,W_2} \subset {\mathbb{P}}(W_1^\vee \otimes W_2^\vee)$.
\end{itemize}
Furthermore, $X_K$ is smooth if and only if the line ${\mathbb{P}}(K)$ is transversal to ${\mathscr{D}}_{W_1,W_2}$.

Let ${\mathscr{K}} \subset W_1^\vee \otimes W_2^\vee \otimes {\mathscr{O}}_S$ be the tautological rank 2 bundle, 
let ${\mathscr{K}}^\perp \subset W_1 \otimes W_2 \otimes {\mathscr{O}}_S$ be its rank~7 annihilator, and let 
\begin{equation}
\label{eq:cx-p2p2}
{\mathscr{X}} := ({\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)) \times_{{\mathbb{P}}(W_1 \otimes W_2)} {\mathbb{P}}_S({\mathscr{K}}^\perp)
\end{equation}
be the corresponding du Val family of sextic del Pezzo surfaces.

\label{proposition:dp-p2p2}
Let ${\mathscr{X}} \to S$ be the du Val family of sextic del Pezzo surfaces defined by~\textup{\eqref{eq:cx-p2p2}}. 
Then 
\begin{equation*}
