\qquad\text{and}\qquad 
\mu_3 \colon {\mathscr{Z}}'_3 \to {\mathscr{Z}}_3({\mathscr{X}}/S)
\end{equation*}
such that the Brauer classes $\mu_2^*(\beta_{{\mathscr{Z}}_2})$ and $\mu_3^*(\beta_{{\mathscr{Z}}_3})$ are trivial 
and ${\mathscr{E}}_2$ and ${\mathscr{E}}_3$ are isomorphic (up to twists by line bundles on~${\mathscr{Z}}'_2$ and ${\mathscr{Z}}'_3$) 
to the pullbacks of the universal bundles ${\mathscr{E}}_{{\mathscr{Z}}_2}$ and ${\mathscr{E}}_{{\mathscr{Z}}_3}$, respectively.
This means that for $d \in \{2,3\}$ we have isomorphisms of Fourier--Mukai functors
\begin{equation*}
\Phi_{{\mathscr{E}}_{d}} \cong \Phi_{{\mathscr{E}}_{{\mathscr{Z}}_d}} \circ \mu_{d*} \circ T_d \colon {\mathbf{D}}({\mathscr{Z}}'_d) \to {\mathbf{D}}({\mathscr{X}}),
\end{equation*}
where $T_d$ is a line bundle twist in ${\mathbf{D}}({\mathscr{Z}}'_d)$.

Since both $\Phi_{{\mathscr{E}}_{{\mathscr{Z}}_d}}$ and $\Phi_{{\mathscr{E}}_d}$ are fully faithful, 
so is the composition $\mu_{d*} \circ T_d \colon {\mathbf{D}}({\mathscr{Z}}'_d) \to {\mathbf{D}}({\mathscr{Z}}_d)$.
Moreover, comparing semiorthogonal decompositions given by~\eqref{eq:dbcx-again} and~\eqref{eq:sod-cx-p2p2}, we conclude that $\mu_{d*} \circ T_d$ is essentially surjective, i.e., an equivalence of categories.
Since $T_d$ is also an equivalence, we conclude that $\mu_{d*}$ is an equivalence, hence $\mu_d$ is an isomorphism.
Thus ${\mathscr{Z}}'_d \cong {\mathscr{Z}}_d({\mathscr{X}}/S)$ and the Brauer classes $\beta_{{\mathscr{Z}}_2}$ and $\beta_{{\mathscr{Z}}_3}$  on~${\mathscr{Z}}_2({\mathscr{X}}/S)$ and~${\mathscr{Z}}_3({\mathscr{X}}/S)$ vanish.

