\rangle.
\end{multline*}

Next, mutating the second component one step to the left, we get
\begin{multline}\label{eq:dbxx3-2}
{\mathbf{D}}({{\mathscr{X}}_2}) = \langle \Phi({\mathbf{D}}({{\mathbb{Y}}_2})), \\
{\mathbf{D}}({\mathbb{P}}({\mathbb{W}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_2}(1,0),
{\mathbf{D}}({\mathbb{P}}({\mathbb{W}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_2}(0,1), 
{\mathbf{D}}({\mathbb{P}}({\mathbb{W}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_2}(1,1), \\
{\mathbf{D}}({\mathbb{P}}({\mathbb{W}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_2}(2,1), 
{\mathbf{D}}({\mathbb{P}}({\mathbb{W}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_2}(1,2), 
{\mathbf{D}}({\mathbb{P}}({\mathbb{W}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_2}(2,2)
\rangle.
\end{multline}
where $\Phi = {\mathbb{L}}_{{\mathbf{D}}({\mathbb{P}}({\mathbb{W}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_2}(1,0)} \circ i_* \circ \phi^* \colon {\mathbf{D}}({{\mathbb{Y}}_2}) \to {\mathbf{D}}({{\mathscr{X}}_2})$.

This almost proves the result. 
The only small thing left is to show that the functor $\Phi$ is a Fourier--Mukai functor 
whose kernel is supported on the fiber product ${{\mathbb{Y}}_2} \times_{{\mathbb{P}}({\mathbb{W}}^\vee)} {{\mathscr{X}}_2}$.
For this we note that by~\eqref{diagram:yy-cx3} the functor $i_* \circ \phi^*$ is a Fourier--Mukai functor 
with kernel $j_*{\mathscr{O}}_{{{\mathbb{Y}}_2} \times {\mathbb{P}}(W_2)}$, 
where $j \colon {\mathbb{Y}}_2 \times {\mathbb{P}}(W_2) \to {\mathbb{Y}}_2 \times_{{\mathbb{P}}({\mathbb{W}}^\vee)} {\mathscr{X}}_2$ is the embedding 
induced by the commutative square~\eqref{diagram:yy-cx3}.
Moreover, using notation from the diagram~\eqref{diagram:yy-cx3}, 
the projection functor onto ${\mathbf{D}}({\mathbb{P}}({\mathbb{W}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_2}(1,0)$ is given by
\begin{equation*}
{\mathscr{F}} \mapsto p_{{\mathscr{X}}_2}^*(p_2^*p_{2*}(p_{{\mathscr{X}}_2*}{\mathscr{F}} \otimes {\mathscr{O}}_{{\mathbb{P}}(W_1)}(-1)) \otimes {\mathscr{O}}_{{\mathbb{P}}(W_1)}(1)),
\end{equation*}
and its composition with $i_* \circ \phi^*$ is given by
\begin{equation*}
{\mathscr{F}} \mapsto p_{{\mathscr{X}}_2}^*(p_2^*p_{2*}(p_{{\mathbb{Y}}_2*}{\mathscr{F}} \otimes {\mathscr{O}}_{{\mathbb{P}}(W_1)}(-1)) \otimes {\mathscr{O}}_{{\mathbb{P}}(W_1)}(1)).
\end{equation*}
In other words, this composition is a Fourier--Mukai functor with kernel $p_{{\mathbb{Y}}_2}^*({\mathscr{O}}_{{\mathbb{P}}(W_1)}(-1)) \boxtimes p_{{\mathscr{X}}_2}^*({\mathscr{O}}_{{\mathbb{P}}(W_1)}(1))$ on ${\mathbb{Y}}_2 \times_{{\mathbb{P}}({\mathbb{W}}^\vee)} {\mathscr{X}}_2$.
Therefore, the functor $\Phi$ fits into a distinguished triangle
\begin{equation*}
\Phi_{p_{{\mathbb{Y}}_2}^*({\mathscr{O}}_{{\mathbb{P}}(W_1)}(-1)) \boxtimes p_{{\mathscr{X}}_2}^*({\mathscr{O}}_{{\mathbb{P}}(W_1)}(1))} \to \Phi_{j_*{\mathscr{O}}_{{{\mathbb{Y}}_2} \times {\mathbb{P}}(W_2)}} \to \Phi.
\end{equation*}
It follows from~\eqref{diagram:yy-cx3} that 
\begin{equation*}
j^*(p_{{\mathbb{Y}}_2}^*({\mathscr{O}}_{{\mathbb{P}}(W_1)}(-1)) \boxtimes p_{{\mathscr{X}}_2}^*({\mathscr{O}}_{{\mathbb{P}}(W_1)}(1))) \cong {\mathscr{O}}_{{{\mathbb{Y}}_2} \times {\mathbb{P}}(W_2)}, 
\end{equation*}
hence by~\cite{anno2012adjunction} the above triangle of functors is induced by (a rotation of the twist of) 
the triangle associated with the standard exact sequence
\begin{equation*}
0 \to {\mathscr{I}}_{{{\mathbb{Y}}_2} \times {\mathbb{P}}(W_2), {{\mathbb{Y}}_2} \times_{{\mathbb{P}}({\mathbb{W}}^\vee)} {{\mathscr{X}}_2}} \to {\mathscr{O}}_{{{\mathbb{Y}}_2} \times_{{\mathbb{P}}({\mathbb{W}}^\vee)} {{\mathscr{X}}_2}} \to j_*{\mathscr{O}}_{{{\mathbb{Y}}_2} \times {\mathbb{P}}(W_2)} \to 0.
\end{equation*}
It finally proves, that up to an irrelevant shift, the functor $\Phi$ is indeed a Fourier--Mukai functor with the kernel
\begin{equation}\label{eq:hpd-kernel-xx3}
{\mathbb{E}}_2 := {\mathscr{I}}_{{{\mathbb{Y}}_2} \times {\mathbb{P}}(W_2), {{\mathbb{Y}}_2} \times_{{\mathbb{P}}({\mathbb{W}}^\vee)} {{\mathscr{X}}_2}} \otimes (p_{{\mathbb{Y}}_2}^*({\mathscr{O}}_{{\mathbb{P}}(W_1)}(-1)) \boxtimes p_{{\mathscr{X}}_2}^*({\mathscr{O}}_{{\mathbb{P}}(W_1)}(1))) \in {\mathbf{D}}({{\mathbb{Y}}_2} \times_{{\mathbb{P}}({\mathbb{W}}^\vee)} {\mathscr{X}}_2),
\end{equation}
and thus completes the proof of the theorem.

Let ${{\mathscr{X}}_3} \subset {{\mathbb{X}}_3} \times {\mathbb{P}}({\mathbb{V}}^\vee)$ be the universal hyperplane section of ${{\mathbb{X}}_3}$.
By~\cite[Theorem~8.2]{kuznetsov2007hpd}, there is a semiorthogonal decomposition
\begin{equation}\label{eq:dbxx1}
{\mathbf{D}}({{\mathscr{X}}_3}) = \langle i_*\phi^*({\mathbf{D}}({{\mathbb{Y}}_3})), {\mathbf{D}}({\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,1,1) \rangle,
\end{equation}
where the morphisms $i$ and $\phi$ are defined by the commutative diagram
\begin{equation}\label{diagram:yy-cx}
\vcenter{\xymatrix{
{{\mathbb{Y}}_3} \times {\mathbb{P}}(V_3) \ar[r]^-i \ar[d]_\phi & {{\mathscr{X}}_3} \ar[d]^{p_{{\mathscr{X}}_3}} \\
{{\mathbb{Y}}_3} \ar[r]^-{p_{{\mathbb{Y}}_3}} & {\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}({\mathbb{V}}^\vee) \ar[r] & {\mathbb{P}}({\mathbb{V}}^\vee)
}}
\end{equation}
and the map $p_{{\mathbb{Y}}_3}$ is induced by the embedding ${\mathscr{V}}_3^\perp \hookrightarrow {\mathbb{V}}^\vee \otimes {\mathscr{O}}_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)}$.
We modify~\eqref{eq:dbxx1} by a sequence of mutations to change it to the form we need.

First, using the standard exceptional collection 
\begin{equation*}
{\mathbf{D}}({\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)) = \langle {\mathscr{O}}_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)}, {\mathscr{O}}_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)}(1,0), {\mathscr{O}}_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)}(0,1), {\mathscr{O}}_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)}(1,1) \rangle
\end{equation*}
in ${\mathbf{D}}({\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2))$, 
we rewrite \eqref{eq:dbxx1} as
\begin{multline*}
{\mathbf{D}}({{\mathscr{X}}_3}) = \langle i_*\phi^*({\mathbf{D}}({{\mathbb{Y}}_3})), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,1,1), \\ {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(2,1,1), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,2,1), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(2,2,1) \rangle.
\end{multline*}
Mutating the last component to the far left, and taking into account that $\omega_{{\mathscr{X}}_3} \cong {\mathscr{O}}_{{\mathbb{X}}_3}(-1,-1,-1)$ up to a line bundle pulled back from ${\mathbb{P}}({\mathbb{V}}^\vee)$, we get a semiorthogonal decomposition
\begin{multline*}
{\mathbf{D}}({{\mathscr{X}}_3}) = \langle {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,1,0), i_*\phi^*({\mathbf{D}}({{\mathbb{Y}}_3})), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,1,1), \\ {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(2,1,1), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,2,1) \rangle.
\end{multline*}

Next, mutating the second component to the left, we get
\begin{multline*}
{\mathbf{D}}({{\mathscr{X}}_3}) = \langle \Phi({\mathbf{D}}({{\mathbb{Y}}_3})), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,1,0), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,1,1), \\ {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(2,1,1), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,2,1) \rangle.
\end{multline*}
where $\Phi = {\mathbb{L}}_{{\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,1,0)} \circ i_* \circ \phi^* \colon {\mathbf{D}}({{\mathbb{Y}}_3}) \to {\mathbf{D}}({{\mathscr{X}}_3})$.

Finally, mutating the second component to the far right and using the pullback 
of the standard exact sequence $0 \to {\mathscr{O}}_{{\mathbb{P}}(V_3)} \to V_3 \otimes {\mathscr{O}}_{{\mathbb{P}}(V_3)}(1) \to {\mathscr{O}}_{{\mathbb{P}}(V_3)}(2) \to 0$, we obtain
\begin{multline}\label{eq:dbxx6}
{\mathbf{D}}({{\mathscr{X}}_3}) = \langle \Phi({\mathbf{D}}({{\mathbb{Y}}_3})), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,1,1), \\ {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(2,1,1), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,2,1), {\mathbf{D}}({\mathbb{P}}({\mathbb{V}}^\vee)) \otimes {\mathscr{O}}_{{\mathbb{X}}_3}(1,1,2) \rangle.
\end{multline}

As before, this almost proves the result. 
The only small thing left is to show that the functor $\Phi$ is a Fourier--Mukai functor 
whose kernel is supported on the fiber product ${{\mathbb{Y}}_3} \times_{{\mathbb{P}}({\mathbb{V}}^\vee)} {{\mathscr{X}}_3}$.
The same computations as in the proof of Theorem~\ref{theorem:hpd-p2p2} show that the functor~$\Phi$ fits into a distinguished triangle
\begin{equation*}
\Phi_{p_{{\mathbb{Y}}_3}^*({\mathscr{O}}_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)}(-1,-1)) \boxtimes p_{{\mathscr{X}}_3}^*({\mathscr{O}}_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)}(1,1))} \to \Phi_{j_*{\mathscr{O}}_{{{\mathbb{Y}}_3} \times {\mathbb{P}}(V_3)}} \to \Phi,
\end{equation*}
with notation introduced in~\eqref{diagram:yy-cx}.
Again, it follows that this triangle is associated (up to a twist and a rotation) with the standard exact sequence
\begin{equation*}
0 \to {\mathscr{I}}_{{{\mathbb{Y}}_3} \times {\mathbb{P}}(V_3), {{\mathbb{Y}}_3} \times_{{\mathbb{P}}({\mathbb{V}}^\vee)} {{\mathscr{X}}_3}} \to {\mathscr{O}}_{{{\mathbb{Y}}_3} \times_{{\mathbb{P}}({\mathbb{V}}^\vee)} {{\mathscr{X}}_3}} \to j_*{\mathscr{O}}_{{{\mathbb{Y}}_3} \times {\mathbb{P}}(V_3)} \to 0,
\end{equation*}
hence 
the functor $\Phi$ is indeed a Fourier--Mukai functor with kernel
\begin{equation}\label{eq:hpd-kernel-xxx3}
{\mathbb{E}}_3 := {\mathscr{I}}_{{{\mathbb{Y}}_3} \times {\mathbb{P}}(V_3), {{\mathbb{Y}}_3} \times_{{\mathbb{P}}({\mathbb{V}}^\vee)} {{\mathscr{X}}_3}} \otimes (p_{{\mathbb{Y}}_3}^*({\mathscr{O}}_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)}(-1,-1)) \boxtimes p_{{\mathscr{X}}_3}^*({\mathscr{O}}_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)}(1,1)))
\end{equation}
and thus completes the proof of the theorem.
